CREATE TYPE "TechnicalExperienceStatus" AS ENUM ('DRAFT','VALIDATED','RESTRICTED','EXPIRED');
CREATE TABLE "executed_contracts" ("id" UUID NOT NULL,"code" VARCHAR(50) NOT NULL,"contractorName" VARCHAR(255) NOT NULL,"contractorIdentifier" VARCHAR(80),"contractorSource" VARCHAR(500) NOT NULL,"subject" TEXT NOT NULL,"startedAt" DATE NOT NULL,"endedAt" DATE NOT NULL,"value" DECIMAL(19,4),"currency" CHAR(3),"status" "TechnicalExperienceStatus" NOT NULL DEFAULT 'DRAFT',"ownerId" UUID NOT NULL,"evidenceDocumentVersionId" UUID NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdBy" UUID NOT NULL,"updatedAt" TIMESTAMPTZ(6) NOT NULL,"updatedBy" UUID NOT NULL,CONSTRAINT "executed_contracts_pkey" PRIMARY KEY("id"),CONSTRAINT "executed_contracts_period_valid" CHECK("endedAt">="startedAt"),CONSTRAINT "executed_contracts_value_nonnegative" CHECK("value" IS NULL OR "value">=0));
CREATE TABLE "executed_works" ("id" UUID NOT NULL,"contractId" UUID NOT NULL,"name" VARCHAR(255) NOT NULL,"location" VARCHAR(255) NOT NULL,"type" VARCHAR(120) NOT NULL,"startedAt" DATE NOT NULL,"endedAt" DATE NOT NULL,"characteristics" TEXT NOT NULL,"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdBy" UUID NOT NULL,CONSTRAINT "executed_works_pkey" PRIMARY KEY("id"),CONSTRAINT "executed_works_period_valid" CHECK("endedAt">="startedAt"));
CREATE TABLE "executed_services" ("id" UUID NOT NULL,"contractId" UUID NOT NULL,"workId" UUID,"discipline" VARCHAR(120) NOT NULL,"originalDescription" TEXT NOT NULL,"characteristics" TEXT NOT NULL,"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdBy" UUID NOT NULL,CONSTRAINT "executed_services_pkey" PRIMARY KEY("id"));
CREATE TABLE "executed_quantities" ("id" UUID NOT NULL,"serviceId" UUID NOT NULL,"value" DECIMAL(19,6) NOT NULL,"unit" VARCHAR(40) NOT NULL,"source" VARCHAR(500) NOT NULL,"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdBy" UUID NOT NULL,CONSTRAINT "executed_quantities_pkey" PRIMARY KEY("id"),CONSTRAINT "executed_quantities_value_positive" CHECK("value">0));
CREATE TABLE "technical_experience_history" ("id" UUID NOT NULL,"contractId" UUID NOT NULL,"version" INTEGER NOT NULL,"action" VARCHAR(80) NOT NULL,"snapshot" JSONB NOT NULL,"reason" VARCHAR(1000),"changedAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"changedById" UUID NOT NULL,"correlationId" UUID NOT NULL,CONSTRAINT "technical_experience_history_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "executed_contracts_code_key" ON "executed_contracts"("code");CREATE INDEX "executed_contracts_status_startedAt_endedAt_idx" ON "executed_contracts"("status","startedAt","endedAt");CREATE INDEX "executed_contracts_ownerId_status_idx" ON "executed_contracts"("ownerId","status");CREATE INDEX "executed_contracts_evidenceDocumentVersionId_idx" ON "executed_contracts"("evidenceDocumentVersionId");CREATE INDEX "executed_works_contractId_type_idx" ON "executed_works"("contractId","type");CREATE INDEX "executed_services_contractId_discipline_idx" ON "executed_services"("contractId","discipline");CREATE INDEX "executed_services_workId_idx" ON "executed_services"("workId");CREATE INDEX "executed_quantities_serviceId_unit_idx" ON "executed_quantities"("serviceId","unit");CREATE UNIQUE INDEX "technical_experience_history_contractId_version_key" ON "technical_experience_history"("contractId","version");CREATE INDEX "technical_experience_history_changedById_changedAt_idx" ON "technical_experience_history"("changedById","changedAt");CREATE INDEX "technical_experience_history_correlationId_idx" ON "technical_experience_history"("correlationId");
ALTER TABLE "executed_contracts" ADD CONSTRAINT "executed_contracts_ownerId_fkey" FOREIGN KEY("ownerId") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "executed_contracts" ADD CONSTRAINT "executed_contracts_evidenceDocumentVersionId_fkey" FOREIGN KEY("evidenceDocumentVersionId") REFERENCES "managed_document_versions"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "executed_works" ADD CONSTRAINT "executed_works_contractId_fkey" FOREIGN KEY("contractId") REFERENCES "executed_contracts"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "executed_services" ADD CONSTRAINT "executed_services_contractId_fkey" FOREIGN KEY("contractId") REFERENCES "executed_contracts"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "executed_services" ADD CONSTRAINT "executed_services_workId_fkey" FOREIGN KEY("workId") REFERENCES "executed_works"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "executed_quantities" ADD CONSTRAINT "executed_quantities_serviceId_fkey" FOREIGN KEY("serviceId") REFERENCES "executed_services"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "technical_experience_history" ADD CONSTRAINT "technical_experience_history_contractId_fkey" FOREIGN KEY("contractId") REFERENCES "executed_contracts"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "technical_experience_history" ADD CONSTRAINT "technical_experience_history_changedById_fkey" FOREIGN KEY("changedById") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE OR REPLACE FUNCTION prevent_technical_experience_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'technical_experience_history is append-only'; END; $$;CREATE TRIGGER technical_experience_history_append_only BEFORE UPDATE OR DELETE ON "technical_experience_history" FOR EACH ROW EXECUTE FUNCTION prevent_technical_experience_history_mutation();
